// /agt flag autocomplete: rows for the token at the cursor while a typed /agt prompt is being written.

// Mirror of skills/agt/SKILL.md: the one optional level word right after /agt, and the one flag left.
export const AGT_LEVELS = [
  { text: 'low', description: 'one stream, may run solo' },
  { text: 'medium', description: '2-3 small streams as subagents' },
  { text: 'heavy', description: 'worker panes in Herdr or tmux' },
  { text: 'next', description: 'build the next item of .agentille/backlog.md' },
]
export const AGT_FLAGS = [{ text: '--fable', description: 'Fable ceiling on judgment roles' }]

const CMD = /^\/(agentille:)?agt$/

const WS = /\s/

// The whitespace-delimited word before `start`, found by scanning back from it: the cost is that word's
// length, not the draft's, and this runs on every keystroke.
function wordBefore(text, start) {
  const t = String(text)
  const space = (i) => WS.test(t[i])
  let end = Math.min(start, t.length)
  while (end > 0 && space(end - 1)) end--
  let at = end
  while (at > 0 && !space(at - 1)) at--
  return t.slice(at, end)
}

// Rows for the token, or [] when the token is the command itself or nothing matches. The first word
// after /agt completes to the levels; a dash completes to the flag. The draft is known to be a typed
// /agt one: registerAutocomplete's matcher lets nothing else through.
export function agtSuggestions({ text, token, start }) {
  if (typeof token !== 'string' || !(start > 0)) return []
  const match = (rows) => rows.filter((r) => r.text.startsWith(token) && r.text !== token)
  if (token === '-' || token.startsWith('--')) return match(AGT_FLAGS)
  return CMD.test(wordBefore(text, start)) ? match(AGT_LEVELS) : []
}

// Fires on every keystroke: answer next(e) at once when there is nothing to add.
export async function autocompleteHook($, e, next) {
  const rows = agtSuggestions(e)
  if (!rows.length) return next(e)
  const r = await next(e)
  return { suggestions: [...(r?.suggestions ?? []), ...rows] }
}

export function registerAutocomplete(on, _ctx) {
  on('prompt.autocomplete', { text: /^\s*\/(agentille:)?agt(\s|$)/ }, autocompleteHook)
}

files.hooks/drawing.js:
// agentille mod — what /agt can leave to the mod when the mod draws: the version and the phases
// on the band, the one-time tip, and the Agents and Raw reports sections of report.md.
// Pure: register.js reads the surfaces and the files, this decides and formats.

import { elapsed, short, tokens } from './live.js'

// Surfaces that show a mod's band. `$.session.surfaces()` names terminal, desktop, vscode or mobile, and is
// empty in `claude -p` and the SDK; the VS Code chat panel runs hooks but draws nothing, and Remote Control
// draws in the machine's terminal, which the list names too.
const DRAWN = new Set(['terminal', 'desktop'])

export const TIP = 'tip: /agentille-init makes agents sound like you'

export function canDraw(surfaces) {
  return (surfaces ?? []).some((s) => DRAWN.has(s))
}

// The marker the skill looks for (display.md → "When the mod draws"). Absent: the skill prints it all itself.
export function drawingBlock(draws) {
  if (!draws) return ''
  return '\n## Drawing (agentille mod)\n\nmod draws: yes. The band shows the version and the phases (no TodoWrite spine), the mod shows the tip and adds Agents and Raw reports to report.md.\n'
}

// `…/.agentille/state/run-<id>/report.md` → the run id, else null.
export function reportRun(path) {
  const m = /\/\.agentille\/state\/run-([A-Za-z0-9_-]{1,64})\/report\.md$/.exec(String(path ?? ''))
  return m ? m[1] : null
}

// The sections the mod owns, for whichever of them the report still lacks. '' when it has both.
export function reportTail(text, { agents = [], routes = [], files = [] }) {
  const out = []
  if (!/^## Agents[ \t]*\r?$/m.test(text)) {
    const rows = [...agents].sort((a, b) => a.start - b.start).map((a) =>
      '| ' + a.role + ' | ' + short(a.model) + (a.effort ? ' · ' + a.effort : '') + ' | ' + elapsed((a.end ?? a.start) - a.start) + ' | ' + tokens(a.input) + ' / ' + tokens(a.output) + ' |')
    for (const r of routes) rows.push('| ' + (r.agent ?? r.role) + ' (pane) | ' + short(r.model) + (r.effort ? ' · ' + r.effort : '') + ' | ' + elapsed((r.end ?? r.start) - r.start) + ' | n/a |')
    if (rows.length) out.push('## Agents', '', '| role | model · effort | elapsed | tokens in / out |', '|---|---|---|---|', ...rows, '')
  }
  if (!/^## Raw reports[ \t]*\r?$/m.test(text) && files.length) {
    out.push('## Raw reports', '', ...[...files].sort().map((f) => '- [' + f + '](agents/' + f + ')'), '')
  }
  if (!out.length) return ''
  return (text.endsWith('\n') ? '\n' : '\n\n') + out.join('\n')
}

